from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import FreeplayURI


class FreeplayV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_redfish_credentials(self, node_id, username=None, timeout=60):
        uri = FreeplayURI().freeplay_redfish_uri + '/' + node_id
        user_list = self.api_client.send_get_request(uri=uri, timeout=timeout)
        if username:
            user_list = [user for user in user_list if user['user'] == username]
        return user_list

    def set_redfish_credentials(self, node_id, username, password=None, privilege=None, timeout=60):
        uri = FreeplayURI().freeplay_redfish_uri
        data = {
            "nodeid": node_id,
            "credentials": {
                "user": username,
                "privilege": privilege if privilege else 'Administrator'
            }
        }
        if password:
            data['credentials']['pass'] = password
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def delete_redfish_credentials(self, node_id, username, timeout=60):
        uri = FreeplayURI().freeplay_redfish_uri
        data = {
            "nodeid": node_id,
            "credentials": {
                "user": username
            }
        }
        return self.api_client.send_delete_request(uri=uri, json=data, timeout=timeout)

    def get_management_credentials(self, node_id, username=None, timeout=60):
        uri = FreeplayURI().freeplay_list_uri + '/' + node_id
        user_list = self.api_client.send_get_request(uri=uri, timeout=timeout)
        if username:
            user_list = [user for user in user_list if user['user'] == username]
        return user_list

    def set_management_credentials(self, node_id, username, password, privilege=None, force_change=True, timeout=60):
        uri = FreeplayURI().freeplay_uri
        data = {"nodeid": node_id,
                "credentials": {
                    "user": username,
                    "pass": password,
                    "privilege": privilege if privilege else 'administrator',
                    "force_change": force_change
                    }
                }
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def delete_management_credentials(self, node_id, username, timeout=60):
        uri = FreeplayURI().freeplay_uri
        data = {
            "nodeid": node_id,
            "credentials": {
                "user": username
            }
        }
        return self.api_client.send_delete_request(uri=uri, json=data, timeout=timeout)
